<?php require_once __DIR__.'/lib.php';$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT p.title,p.original_filename,f.* FROM audit_findings f JOIN projects p ON p.id=f.project_id WHERE p.id=? ORDER BY f.id');$s->execute([$id]);$rows=$s->fetchAll();if(!$rows){http_response_code(404);exit('ไม่พบข้อมูล');}header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="skru-audit-'.$id.'.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['หลักสูตร','ไฟล์','รหัสตรวจ','หมวด','ประเด็น','สถานะ','ระดับ','หลักฐาน','หน้า','ข้อเสนอแนะ','แหล่งผลตรวจ','ความเห็นกรรมการ']);foreach($rows as $r)fputcsv($out,[$r['title'],$r['original_filename'],$r['check_id'],$r['category'],$r['title'],$r['status'],$r['severity'],$r['evidence'],$r['page_no'],$r['recommendation'],$r['source'],$r['reviewer_comment']]);fclose($out);